cd /work; build(){ psql -qX -v ON_ERROR_STOP=1 -f source/schema.sql 2>/dev/null && python3 source/seed.py --print-only | psql -qX -v ON_ERROR_STOP=1 && psql -qX -v ON_ERROR_STOP=1 -f dashboard_schema.sql 2>/dev/null; }
run2(){ for i in 1 2; do psql -qX -v ON_ERROR_STOP=1 -f etl.sql; echo "exit=$?"; psql -X -At -c "select (select count(*) from dash_revenue_by_category),(select count(*) from dash_revenue_by_country),(select md5(string_agg(t::text,',' order by month,category)) from dash_revenue_by_category t),(select md5(string_agg(t::text,',' order by month,country)) from dash_revenue_by_country t)"; done; psql -X -At -c "select run_id,source_order_count,loaded_order_count,mismatch from etl_run_log order by 1"; }
echo "== PURE SEED =="; build && run2
echo "== SEED + §5 EDGE CASES =="; build && psql -qX -v ON_ERROR_STOP=1 -f /tmp/etltest/edge.sql && run2
psql -X -c "select * from dash_revenue_by_category where month='2030-01' order by 2" -c "select * from dash_revenue_by_country where month='2030-01' order by 2"

